// 1. Parse incoming data (GET or POST)
const input = $input.first().json;
let body = {};
try {
  body = (input.query && input.query.data)
    ? JSON.parse(input.query.data)
    : (input.body || input);
} catch (e) {
  body = {};
}

const payload = body.data || body;

// Sanitize and validate inputs
const sanitize = (str, maxLen = 500) => {
  if (typeof str !== 'string') return '';
  return str.slice(0, maxLen).trim();
};

const validateStudentId = (id) => {
  // Convert to integer, default to 999 for guest
  if (!id || id === 'guest' || id === 'STU_DEFAULT') return 999;
  const parsed = parseInt(id);
  return isNaN(parsed) ? parsed : 999;
};

const allowedSubjects = ['Maths', 'English', 'Science', 'Biology', 'Chemistry', 'Physics', 'History', 'Geography', 'Computer Science', 'General'];
const normalizeSubject = (subj) => {
  if (typeof subj !== 'string') return 'General';
  const match = allowedSubjects.find(s => s.toLowerCase() === subj.toLowerCase().trim());
  return match || 'General';
};

// Get action type
const action = body.action || 'ask_tutor';
const studentId = validateStudentId(body.studentId || body.userId);
const question = sanitize(payload.question || 'Hello', 1000);
const subject = normalizeSubject(payload.subject || body.subject);
const count = parseInt(payload.count) || 5;
const difficulty = payload.difficulty || 'medium';
const topic = sanitize(payload.topic || '', 200);

if (!question && action !== 'get_history') {
  throw new Error('Question is required');
}

return {
  action,
  studentId,
  question,
  subject,
  count,
  difficulty,
  topic,
  timestamp: new Date().toISOString()
};

// Build GCSE-optimized prompt
const student = $input.first().json;
const request = $("Parse Request").first().json;

// Determine student rank based on XP
const getRank = (xp) => {
  if (xp >= 1000) return 'Scholar';
  if (xp >= 500) return 'Apprentice';
  if (xp >= 100) return 'Learner';
  return 'Initiate';
};

const rank = getRank(student.current_level || 0);
const level = student.current_level || 1;

// Check action type
const action = request.action || 'ask_tutor';
let prompt;

if (action === 'generate_quiz') {
  // Quiz generation prompt
  const difficultyDesc = {
    easy: 'basic recall and understanding questions suitable for foundation tier',
    medium: 'application and analysis questions suitable for crossover grades 4-6',
    hard: 'evaluation and synthesis questions suitable for higher tier grades 7-9'
  };

  prompt = `Generate exactly ${request.count} GCSE ${request.subject} multiple choice quiz questions${request.topic ? ` about "${request.topic}"` : ''}.
Difficulty: ${request.difficulty} (${difficultyDesc[request.difficulty]})

IMPORTANT: Respond ONLY with valid JSON, no markdown, no explanation. Use this exact format:
{
  "questions": [
    {
      "question": "Question text here?",
      "options": ["A) First option", "B) Second option", "C) Third option", "D) Fourth option"],
      "correct": 0,
      "explanation": "Brief explanation of why the answer is correct and common misconceptions."
    }
  ]
}

Rules:
- Each question must have exactly 4 options labeled A) B) C) D)
- "correct" is the index (0-3) of the correct answer
- Make questions exam-style and appropriate for UK GCSE
- Include a mix of question types (recall, application, analysis)
- Explanations should mention mark scheme points where relevant`;
} else {
  // Standard Q&A prompt
  prompt = `You are an expert GCSE ${request.subject} tutor specialising in UK exam preparation.

## Your Teaching Approach
- Align explanations with AQA/Edexcel/OCR GCSE specifications
- Reference mark scheme requirements when relevant (e.g., "For full marks, you need to...")
- Use command word definitions (Explain = state + reason, Evaluate = pros/cons + judgement)
- Break complex topics into digestible chunks suitable for 14-16 year olds
- Include exam technique tips where applicable
- Use real-world examples relatable to teenagers

## Student Context
- Level: ${level} | Rank: ${rank}
- XP: ${student.xp_points || 0} points
- Subject focus: ${request.subject}

## Student Question
"${request.question}"

## Response Guidelines
1. Start with a direct answer to the question
2. Provide a clear explanation with examples
3. If relevant, mention how this might appear in an exam
4. End with a follow-up question or challenge to reinforce learning

Keep your response focused, encouraging, and under 400 words unless the topic requires more depth.`;
}

return {
  prompt,
  action: request.action,
  studentId: student.student_id || request.studentId,
  currentXp: student.xp_points || 0,
  newXp: (student.xp_points || 0) + 10,
  subject: request.subject,
  question: request.question
};

// Prepare data for DB logging
const prepData = $("Prepare Neural Prompt").first().json;
const openAiResponse = $input.first().json;

const aiResponse = openAiResponse?.choices?.[0]?.message?.content 
  || openAiResponse?.output 
  || 'Unable to generate response';

return {
  studentId: prepData.studentId,
  newXp: prepData.newXp,
  subject: prepData.subject,
  question: prepData.question,
  aiResponse: aiResponse
};

