const prepData = $("Prepare Neural Prompt").first().json;

return {
  studentId: prepData.studentId,
  newXp: prepData.currentXp, // Don't award XP on failure
  subject: prepData.subject,
  question: prepData.question,
  aiResponse: "I'm having trouble generating a response right now. Please try again in a moment.",
  isError: true
};

const prepData = $('Prep DB Data').first().json;

return {
  success: true,
  answer: prepData.aiResponse,
  student: {
    id: prepData.studentId,
    xp: prepData.newXp,
    sessions: Math.floor(prepData.newXp / 10)
  },
  meta: {
    subject: prepData.subject,
    timestamp: new Date().toISOString()
  }
};

